115	/// Compute the delay before the next retry attempt.
116	#[must_use]
117	#[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss, clippy::cast_sign_loss)]
118	pub fn next_retry_delay(
119	    config: &RetryConfig,
120	    attempt: u32,
121	    jitter_seed: f64,
122	    retry_after: Option<Duration>,
123	) -> Option<Duration> {
124	    if attempt >= config.max_retries {
125	        return None;
126	    }
127	    let jitter_seed = if jitter_seed.is_finite() { jitter_seed.clamp(0.0, 1.0) } else { 0.0 };
128	    let exp = 2u64.saturating_pow(attempt);
129	    let base_ms = u64::try_from(config.base_delay.as_millis()).unwrap_or(u64::MAX);
130	    let max_ms = u64::try_from(config.max_delay.as_millis()).unwrap_or(u64::MAX);
131	    let raw_ms = base_ms.saturating_mul(exp);
132	    let jitter_ms = (raw_ms as f64 * config.jitter_factor * jitter_seed) as u64;
133	    let jittered_ms = raw_ms.saturating_add(jitter_ms);
134	    let retry_after_ms = retry_after.map_or(0, |d| u64::try_from(d.as_millis()).unwrap_or(u64::MAX));
135	    let capped_ms = jittered_ms.max(retry_after_ms).min(max_ms);
136	    Some(Duration::from_millis(capped_ms))
137	}
