145	/// Like [`parse_retry_after`], but takes the current time explicitly.
146	#[must_use]
147	pub fn parse_retry_after_at(header_value: &str, now: std::time::SystemTime) -> Option<Duration> {
148	    let trimmed = header_value.trim();
149	    if let Ok(secs) = trimmed.parse::<u64>() {
150	        return Some(Duration::from_secs(secs));
151	    }
152	    let target = parse_http_date(trimmed)?;
153	    Some(target.duration_since(now).unwrap_or(Duration::ZERO))
154	}
155	
156	fn parse_http_date(s: &str) -> Option<std::time::SystemTime> {
157	    let s = s.strip_suffix(" GMT")?;
158	    let (_weekday, rest) = s.split_once(", ")?;
159	    let mut parts = rest.split(' ');
160	    let day: u64 = parts.next()?.parse().ok()?;
161	    let month = month_number(parts.next()?)?;
162	    let year: i64 = parts.next()?.parse().ok()?;
163	    if !(0..=9999).contains(&year) {
164	        return None;
165	    }
166	    let time = parts.next()?;
167	    if parts.next().is_some() {
168	        return None;
169	    }
170	    let mut time_parts = time.split(':');
171	    let hour: u64 = time_parts.next()?.parse().ok()?;
172	    let minute: u64 = time_parts.next()?.parse().ok()?;
173	    let second: u64 = time_parts.next()?.parse().ok()?;
174	    let max_day = days_in_month(year, month)?;
175	    if time_parts.next().is_some() || hour > 23 || minute > 59 || second > 60 || day == 0 || day > max_day {
176	        return None;
177	    }
178	
179	    let days = days_from_civil(year, month, day);
180	    #[allow(clippy::cast_possible_wrap)]
181	    let epoch_secs = days.checked_mul(86_400)?.checked_add((hour * 3600 + minute * 60 + second) as i64)?;
182	    let unix_secs = u64::try_from(epoch_secs).ok()?;
183	    Some(std::time::UNIX_EPOCH + Duration::from_secs(unix_secs))
184	}
185	
186	fn days_in_month(year: i64, month: u64) -> Option<u64> {
187	    Some(match month {
188	        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
189	        4 | 6 | 9 | 11 => 30,
190	        2 => {
191	            let is_leap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
192	            if is_leap {
193	                29
194	            } else {
195	                28
196	            }
197	        }
198	        _ => return None,
199	    })
200	}
201	
202	fn month_number(name: &str) -> Option<u64> {
203	    Some(match name {
204	        "Jan" => 1,
205	        "Feb" => 2,
206	        "Mar" => 3,
207	        "Apr" => 4,
208	        "May" => 5,
209	        "Jun" => 6,
210	        "Jul" => 7,
211	        "Aug" => 8,
212	        "Sep" => 9,
213	        "Oct" => 10,
214	        "Nov" => 11,
215	        "Dec" => 12,
216	        _ => return None,
217	    })
218	}
