220	#[allow(clippy::cast_possible_wrap, clippy::cast_possible_truncation, clippy::cast_sign_loss)]
221	fn days_from_civil(y: i64, m: u64, d: u64) -> i64 {
222	    let y = if m <= 2 { y - 1 } else { y };
223	    let era = if y >= 0 { y } else { y - 399 } / 400;
224	    let yoe = (y - era * 400) as u64;
225	    let mp = (m + 9) % 12;
226	    let doy = (153 * mp + 2) / 5 + d - 1;
227	    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
228	    era * 146_097 + doe as i64 - 719_468
229	}
