302	pub fn render_already_done(operation: &str, summary: &str, hints: &[String]) -> String {
303	    let mut out = String::with_capacity(64 + operation.len() + summary.len() + hints.len() * 50);
304	    out.push_str("operation: ");
305	    out.push_str(operation);
306	    out.push_str("\nstatus:    already_done\nsummary:   ");
307	    out.push_str(summary);
