309	    if !hints.is_empty() {
310	        out.push_str("help[");
311	        out.push_str(&hints.len().to_string());
312	        out.push_str("]:\n");
313	        for hint in hints {
314	            out.push_str("  ");
315	            out.push_str(hint);
316	            out.push('\n');
317	        }
318	    }
319	    out
320	}

