  5	//! # michi-truncate
  6	//!
  7	//! UTF-8 char-boundary safe content truncation primitives for michi and AXI.
  8	
  9	/// Result of a truncation operation.
 10	#[derive(Debug, Clone, PartialEq)]
 11	#[non_exhaustive]
 12	pub struct Truncated {
 13	    /// The truncated (or original) content string.
 14	    pub content: String,
 15	    /// Original byte length of the input.
 16	    pub original_len: usize,
 17	    /// Whether truncation actually occurred.
 18	    pub was_truncated: bool,
 19	    /// The truncation signal text that was actually embedded in `content`,
 20	    /// starting immediately after the kept characters (leading space stripped).
 21	    /// `None` when not truncated or when `max_chars` was so small that no
 22	    /// signal text fit.
 23	    pub signal: Option<String>,
 24	}
 25	
 26	/// Truncate `content` to at most `max_chars` Unicode scalar values, appending
 27	/// an agent-readable suffix when truncation occurs.
 28	///
 29	/// The suffix pattern is `" ({n} chars truncated — use {hint})"`. Uses char
 30	/// boundaries — never splits a Unicode scalar.
 31	///
 32	/// Returns the original string unchanged when `content.chars().count() <= max_chars`.
 33	#[must_use]
 34	pub fn truncate(content: &str, max_chars: usize, hint: &str) -> Truncated {
 35	    // Byte length is always >= char count, so if it already fits within
 36	    // max_chars the char count does too — skip the full UTF-8 scan.
 37	    if content.len() <= max_chars {
 38	        return Truncated {
 39	            content: content.to_string(),
 40	            original_len: content.len(),
 41	            was_truncated: false,
 42	            signal: None,
 43	        };
 44	    }
 45	
 46	    let char_count = content.chars().count();
 47	    if char_count <= max_chars {
 48	        return Truncated {
 49	            content: content.to_string(),
 50	            original_len: content.len(),
 51	            was_truncated: false,
 52	            signal: None,
 53	        };
 54	    }
 55	
 56	    let suffix = format!(" ({char_count} chars truncated — use {hint})");
 57	    let suffix_chars = suffix.chars().count();
 58	    let keep_chars = max_chars.saturating_sub(suffix_chars);
 59	
 60	    let byte_end = content.char_indices().nth(keep_chars).map_or(content.len(), |(i, _)| i);
 61	
 62	    let mut result = String::with_capacity(byte_end + suffix.len());
 63	    result.push_str(&content[..byte_end]);
 64	    result.push_str(&suffix);
 65	
 66	    // Hard-cap to max_chars via char boundaries in case the suffix alone
 67	    // exceeds max_chars (e.g. very small max_chars or long hint string).
 68	    if result.chars().count() > max_chars {
 69	        let cap_byte = result.char_indices().nth(max_chars).map_or(result.len(), |(i, _)| i);
 70	        result.truncate(cap_byte);
 71	    }
 72	
 73	    // Recompute signal based on what's actually in content after hard-cap
 74	    let signal = if result.len() > byte_end {
 75	        let signal_text = &result[byte_end..];
